/**
 * Faro Metrics Service
 *
 * Service to query Grafana Faro backend (Loki) for aggregated Real User Monitoring (RUM) metrics
 * to display in the Analytics tab.
 *
 * Data Architecture:
 * ┌─────────────────────────────┬──────────────┬──────────────────────────────────────────────────────────────┐
 * │          Data Type          │ Where Stored │                         How to Query                         │
 * ├─────────────────────────────┼──────────────┼──────────────────────────────────────────────────────────────┤
 * │ Web Vitals (LCP, FCP, TTFB) │ Loki         │ LogQL: {source="faro", type="rum"} |= "faro.performance.resource"        │
 * │ Page Performance            │ Loki         │ LogQL: {source="faro", type="rum"} |= "faro.performance.resource"        │
 * │ Errors                      │ Loki         │ LogQL: {source="faro", type="rum"} |= "kind=exception"                   │
 * │ Events                      │ Loki         │ LogQL: {source="faro", type="rum"} |= "kind=event"                       │
 * │ Collector Metrics           │ Prometheus   │ PromQL: faro_receiver_*                                      │
 * └─────────────────────────────┴──────────────┴──────────────────────────────────────────────────────────────┘
 *
 * Data Format in Loki (key=value in body field):
 * - event_name=faro.performance.resource → Web Vitals & Page Performance
 * - event_name=faro.tracing.fetch → HTTP fetch timing
 * - kind=exception → JavaScript errors
 * - kind=event → User events
 *
 * API: https://{env}.logs.docbits.com/loki/api/v1/query_range
 */

import axios, { AxiosError } from 'axios';
import { getLokiApiUrl } from 'src/utils/lokiUrl';
import type {
  CoreWebVitalsData,
  PagePerformanceData,
  ErrorMetricsData,
  UserActivityData,
  DashboardPerformanceData,
  WebSocketPerformanceData,
  ApiPerformanceData,
  BrowserAnalyticsData,
  FaroQueryParams,
  PercentileMetric,
  TimeSeriesPoint,
  ErrorSummary,
  ApiEndpointSummary,
  ApiTrendPoint,
  BrowserSummary,
  OSSummary,
  BrowserTrendPoint,
} from './types';

/**
 * Loki API response types
 */
interface LokiQueryResponse {
  status: 'success' | 'error';
  data: {
    resultType: 'streams' | 'matrix' | 'vector';
    result: LokiStream[];
  };
  error?: string;
}

interface LokiStream {
  stream: Record<string, string>;
  values: Array<[string, string]>; // [timestamp_ns, log_line]
}

interface FaroLogEntry {
  body: string;
  attributes?: Record<string, string>;
  resources?: Record<string, string>;
}

// getLokiApiUrl() imported from src/utils/lokiUrl.ts

/**
 * Convert time range string to milliseconds
 */
function parseTimeRange(timeRange: string): number {
  const match = timeRange.match(/^(\d+)([hmd])$/);
  if (!match) {
    return 24 * 60 * 60 * 1000; // Default 24h
  }

  const value = parseInt(match[1], 10);
  const unit = match[2];

  switch (unit) {
    case 'h':
      return value * 60 * 60 * 1000;
    case 'd':
      return value * 24 * 60 * 60 * 1000;
    case 'm':
      return value * 60 * 1000;
    default:
      return 24 * 60 * 60 * 1000;
  }
}

/**
 * Execute LogQL query against Loki with retry logic
 */
async function executeLokiQuery(
  query: string,
  startMs: number,
  endMs: number,
  limit: number = 5000,
  retries: number = 3
): Promise<LokiQueryResponse> {
  const baseUrl = getLokiApiUrl();

  if (!baseUrl) {
    throw new Error('Loki API not available');
  }

  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      // Loki expects nanosecond timestamps
      const startNs = startMs * 1000000;
      const endNs = endMs * 1000000;

      const response = await axios.get<LokiQueryResponse>(
        `${baseUrl}/query_range`,
        {
          params: {
            query,
            start: startNs.toString(),
            end: endNs.toString(),
            limit,
          },
          timeout: 10000,
        }
      );

      if (response.data.status !== 'success') {
        throw new Error(response.data.error || 'Query failed');
      }

      return response.data;
    } catch (error) {
      lastError = error as Error;

      if (axios.isAxiosError(error)) {
        const axiosError = error as AxiosError;
        if (axiosError.response?.status && axiosError.response.status >= 400 && axiosError.response.status < 500) {
          throw new Error(
            `Loki API error: ${axiosError.response.status} ${axiosError.response.statusText}`
          );
        }

        // Network error - retry with exponential backoff
        if (attempt < retries) {
          const delay = 1000 * Math.pow(2, attempt - 1);
          await new Promise((resolve) => setTimeout(resolve, delay));
          continue;
        }
      }

      if (attempt < retries) {
        const delay = 1000 * Math.pow(2, attempt - 1);
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }

  console.warn(`[FARO/Loki] Query failed after ${retries} retries`);
  throw lastError || new Error('Query failed after retries');
}

/**
 * Parse Faro log body (key=value format) to extract metrics
 */
function parseLogBody(body: string): Record<string, string | number> {
  const result: Record<string, string | number> = {};

  // Handle JSON format
  if (body.startsWith('{')) {
    try {
      const parsed = JSON.parse(body);
      if (parsed.body) {
        return parseLogBody(parsed.body);
      }
      return parsed;
    } catch {
      // Fall through to key=value parsing
    }
  }

  // Parse key=value pairs
  // Handle quoted values and numeric values
  const regex = /(\w+)=("([^"]*)"|([\d.]+)|([^ ]+))/g;
  let match;

  while ((match = regex.exec(body)) !== null) {
    const key = match[1];
    // Quoted value (group 3), numeric value (group 4), or unquoted value (group 5)
    const value = match[3] || match[4] || match[5] || '';

    // Try to parse as number
    const numValue = parseFloat(value);
    result[key] = isNaN(numValue) ? value : numValue;
  }

  return result;
}

/**
 * Extract all log entries from Loki response
 */
function extractLogEntries(response: LokiQueryResponse): FaroLogEntry[] {
  const entries: FaroLogEntry[] = [];

  for (const stream of response.data.result) {
    for (const [timestampNs, logLine] of stream.values) {
      try {
        // Convert Loki timestamp (nanoseconds) to ISO string
        const lokiTimestamp = new Date(parseInt(timestampNs) / 1_000_000).toISOString();

        // Try JSON parse first
        if (logLine.startsWith('{')) {
          const parsed = JSON.parse(logLine);
          // Add Loki timestamp to entry (overwrite if exists)
          parsed._lokiTimestamp = lokiTimestamp;
          entries.push(parsed);
        } else {
          // Plain text log - include Loki timestamp
          entries.push({ body: logLine, _lokiTimestamp: lokiTimestamp } as FaroLogEntry);
        }
      } catch {
        entries.push({ body: logLine });
      }
    }
  }

  return entries;
}

/**
 * Calculate percentiles from array of values
 */
function calculatePercentilesFromValues(values: number[]): PercentileMetric {
  if (values.length === 0) {
    return { p50: 0, p75: 0, p95: 0, p99: 0 };
  }

  // Sort values
  const sorted = [...values].sort((a, b) => a - b);

  const percentile = (p: number): number => {
    const index = Math.ceil((p / 100) * sorted.length) - 1;
    return sorted[Math.max(0, index)];
  };

  return {
    p50: percentile(50),
    p75: percentile(75),
    p95: percentile(95),
    p99: percentile(99),
  };
}

/**
 * Get default percentile metric (all zeros)
 */
function getDefaultPercentile(): PercentileMetric {
  return { p50: 0, p75: 0, p95: 0, p99: 0 };
}

/**
 * Safely get parsed data from a FaroLogEntry
 * Handles both:
 * - Entries with a 'body' string field (needs parsing)
 * - Entries that are already parsed JSON objects (direct metrics)
 */
function getEntryData(entry: FaroLogEntry): Record<string, string | number> {
  if (entry.body !== undefined && typeof entry.body === 'string') {
    return parseLogBody(entry.body);
  }
  // Entry is already a parsed JSON object with direct metrics
  return entry as unknown as Record<string, string | number>;
}

/**
 * Extract metric values from Faro log entries
 */
function extractMetricValues(
  entries: FaroLogEntry[],
  metricName: string
): number[] {
  const values: number[] = [];

  for (const entry of entries) {
    const parsed = getEntryData(entry);
    const value = parsed[metricName];

    if (typeof value === 'number' && !isNaN(value) && value > 0) {
      values.push(value);
    }
  }

  return values;
}

/**
 * Get Core Web Vitals metrics
 *
 * Returns percentiles (P50, P75, P95, P99) for:
 * - TTFB (Time to First Byte)
 * - FCP (First Contentful Paint)
 * - LCP (Largest Contentful Paint)
 * - CLS (Cumulative Layout Shift)
 * - FID (First Input Delay)
 * - INP (Interaction to Next Paint)
 */
export async function getCoreWebVitals(
  params: FaroQueryParams
): Promise<CoreWebVitalsData> {
  const timeRange = params.timeRange || '24h';
  const rangeMs = parseTimeRange(timeRange);
  const endMs = Date.now();
  const startMs = endMs - rangeMs;

  try {
    // Query Loki for faro.performance.resource events (contains web vitals data)
    // Data format: body contains "event_name=faro.performance.resource event_data_ttfb=32 ..."
    const query = '{source="faro", type="rum"} |= "faro.performance.resource"';
    const response = await executeLokiQuery(query, startMs, endMs);
    const entries = extractLogEntries(response);

    // Extract metric values from event_data_* fields
    // The body format uses event_data_ prefix for metrics
    const ttfbValues = extractMetricValues(entries, 'event_data_ttfb')
      .concat(extractMetricValues(entries, 'ttfb'));
    const fcpValues = extractMetricValues(entries, 'event_data_fcp')
      .concat(extractMetricValues(entries, 'fcp'));
    const lcpValues = extractMetricValues(entries, 'event_data_lcp')
      .concat(extractMetricValues(entries, 'lcp'));
    const clsValues = extractMetricValues(entries, 'event_data_cls')
      .concat(extractMetricValues(entries, 'cls'));
    const fidValues = extractMetricValues(entries, 'event_data_fid')
      .concat(extractMetricValues(entries, 'fid'));
    const inpValues = extractMetricValues(entries, 'event_data_inp')
      .concat(extractMetricValues(entries, 'inp'));

    return {
      ttfb: calculatePercentilesFromValues(ttfbValues),
      fcp: calculatePercentilesFromValues(fcpValues),
      lcp: calculatePercentilesFromValues(lcpValues),
      cls: calculatePercentilesFromValues(clsValues),
      fid: calculatePercentilesFromValues(fidValues),
      inp: calculatePercentilesFromValues(inpValues),
    };
  } catch (error) {
    console.error('Failed to fetch Core Web Vitals:', error);
    throw new Error('Core Web Vitals data unavailable');
  }
}

/**
 * Get Page Performance metrics
 *
 * Returns percentiles for:
 * - DNS Lookup time
 * - TCP Connect time
 * - TLS Handshake time
 * - TTFB
 * - DOM Load time
 * - Full Page Load time
 */
export async function getPagePerformance(
  params: FaroQueryParams
): Promise<PagePerformanceData> {
  const timeRange = params.timeRange || '24h';
  const rangeMs = parseTimeRange(timeRange);
  const endMs = Date.now();
  const startMs = endMs - rangeMs;

  try {
    // Query Loki for faro.performance.resource events (contains timing data)
    // Data format: body contains "event_data_dnsLookupTime=0 event_data_tcpHandshakeTime=0 event_data_ttfb=32 ..."
    const query = '{source="faro", type="rum"} |= "faro.performance.resource"';
    const response = await executeLokiQuery(query, startMs, endMs);
    const entries = extractLogEntries(response);

    // Extract metric values from event_data_* fields
    // Check multiple naming conventions: event_data_*, snake_case, camelCase
    const dnsLookupValues = extractMetricValues(entries, 'event_data_dnsLookupTime')
      .concat(extractMetricValues(entries, 'dnsLookupTime'))
      .concat(extractMetricValues(entries, 'dns_lookup'))
      .concat(extractMetricValues(entries, 'dnsLookup'));
    const tcpConnectValues = extractMetricValues(entries, 'event_data_tcpHandshakeTime')
      .concat(extractMetricValues(entries, 'tcpHandshakeTime'))
      .concat(extractMetricValues(entries, 'tcp_connect'))
      .concat(extractMetricValues(entries, 'tcpConnect'));
    const tlsHandshakeValues = extractMetricValues(entries, 'event_data_tlsNegotiationTime')
      .concat(extractMetricValues(entries, 'tlsNegotiationTime'))
      .concat(extractMetricValues(entries, 'tls_handshake'))
      .concat(extractMetricValues(entries, 'tlsHandshake'));
    const ttfbValues = extractMetricValues(entries, 'event_data_ttfb')
      .concat(extractMetricValues(entries, 'ttfb'));
    const domLoadValues = extractMetricValues(entries, 'event_data_duration')
      .concat(extractMetricValues(entries, 'duration'))
      .concat(extractMetricValues(entries, 'dom_load'))
      .concat(extractMetricValues(entries, 'domLoad'));
    const fullPageLoadValues = extractMetricValues(entries, 'event_data_duration')
      .concat(extractMetricValues(entries, 'event_data_fetchTime'))
      .concat(extractMetricValues(entries, 'fetchTime'))
      .concat(extractMetricValues(entries, 'full_page_load'))
      .concat(extractMetricValues(entries, 'fullPageLoad'));

    return {
      dnsLookup: calculatePercentilesFromValues(dnsLookupValues),
      tcpConnect: calculatePercentilesFromValues(tcpConnectValues),
      tlsHandshake: calculatePercentilesFromValues(tlsHandshakeValues),
      ttfb: calculatePercentilesFromValues(ttfbValues),
      domLoad: calculatePercentilesFromValues(domLoadValues),
      fullPageLoad: calculatePercentilesFromValues(fullPageLoadValues),
    };
  } catch (error) {
    console.error('Failed to fetch Page Performance:', error);
    throw new Error('Page Performance data unavailable');
  }
}

/**
 * Get Error Analysis metrics
 *
 * Returns:
 * - JavaScript error count
 * - Console error count
 * - Error rate trend (hourly)
 * - Top 5 error messages
 * - Affected page URLs
 */
export async function getErrorMetrics(
  params: FaroQueryParams
): Promise<ErrorMetricsData> {
  const timeRange = params.timeRange || '24h';
  const rangeMs = parseTimeRange(timeRange);
  const endMs = Date.now();
  const startMs = endMs - rangeMs;

  try {
    // Query Loki for exception logs and error-level logs in parallel
    const exceptionQuery = '{source="faro", type="rum"} |= "kind=exception"';
    const errorQuery = '{source="faro", type="rum"} |= "kind=log" |= "level=error"';
    const [exceptionResponse, errorResponse] = await Promise.all([
      executeLokiQuery(exceptionQuery, startMs, endMs),
      executeLokiQuery(errorQuery, startMs, endMs),
    ]);
    const exceptionEntries = extractLogEntries(exceptionResponse);
    const errorEntries = extractLogEntries(errorResponse);

    // Count errors
    const jsErrorCount = exceptionEntries.length;
    const consoleErrorCount = errorEntries.length;

    // Build error trend (hourly buckets)
    const hourMs = 60 * 60 * 1000;
    const buckets = Math.ceil(rangeMs / hourMs);
    const errorRateTrend: TimeSeriesPoint[] = [];

    for (let i = 0; i < buckets; i++) {
      const bucketStart = startMs + i * hourMs;
      const bucketEnd = bucketStart + hourMs;

      // Count errors in this bucket (simplified - assumes even distribution)
      const fraction = 1 / buckets;
      const value = (jsErrorCount + consoleErrorCount) * fraction;

      errorRateTrend.push({
        timestamp: bucketStart,
        value: Math.round(value),
      });
    }

    // Extract top error messages
    const errorMessages: Record<string, number> = {};
    for (const entry of exceptionEntries) {
      const parsed = getEntryData(entry);
      const message = String(parsed.message || parsed.error || 'Unknown error');
      errorMessages[message] = (errorMessages[message] || 0) + 1;
    }

    const topErrors: ErrorSummary[] = Object.entries(errorMessages)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([message, count]) => ({ message, count }));

    // Extract affected pages
    const pages = new Set<string>();
    for (const entry of exceptionEntries) {
      const parsed = getEntryData(entry);
      if (parsed.page_url) {
        pages.add(String(parsed.page_url));
      }
    }
    const affectedPages = Array.from(pages).slice(0, 10);

    return {
      jsErrorCount,
      consoleErrorCount,
      errorRateTrend,
      topErrors,
      affectedPages,
    };
  } catch (error) {
    console.error('Failed to fetch Error Metrics:', error);
    throw new Error('Error Metrics data unavailable');
  }
}

/**
 * Get User Activity metrics
 *
 * Returns:
 * - Unique sessions
 * - Average session duration
 * - Peak activity hour
 * - Active users now (if available)
 * - Session trend (hourly)
 */
export async function getUserActivity(
  params: FaroQueryParams
): Promise<UserActivityData> {
  const timeRange = params.timeRange || '24h';
  const rangeMs = parseTimeRange(timeRange);
  const endMs = Date.now();
  const startMs = endMs - rangeMs;

  try {
    // Query Loki for session events
    // Data format: body contains "kind=event" as text
    const query = '{source="faro", type="rum"} |= "kind=event"';
    const response = await executeLokiQuery(query, startMs, endMs);
    const entries = extractLogEntries(response);

    // Extract unique session IDs
    const sessions = new Set<string>();
    const hourlyActivity: Record<number, number> = {};

    for (const entry of entries) {
      const parsed = getEntryData(entry);
      if (parsed.session_id) {
        sessions.add(String(parsed.session_id));
      }

      // Track hourly activity
      const timestamp = parsed.timestamp;
      if (timestamp) {
        const date = new Date(String(timestamp));
        const hour = date.getHours();
        hourlyActivity[hour] = (hourlyActivity[hour] || 0) + 1;
      }
    }

    const uniqueSessions = sessions.size;

    // Find peak activity hour
    let peakActivityHour = 0;
    let maxActivity = 0;
    for (const [hour, count] of Object.entries(hourlyActivity)) {
      if (count > maxActivity) {
        maxActivity = count;
        peakActivityHour = parseInt(hour, 10);
      }
    }

    // Build session trend (hourly buckets)
    const hourMs = 60 * 60 * 1000;
    const buckets = Math.ceil(rangeMs / hourMs);
    const sessionTrend: TimeSeriesPoint[] = [];

    for (let i = 0; i < buckets; i++) {
      const bucketStart = startMs + i * hourMs;
      sessionTrend.push({
        timestamp: bucketStart,
        value: Math.round(uniqueSessions / buckets),
      });
    }

    return {
      uniqueSessions,
      avgSessionDuration: 0, // Would need session start/end events
      peakActivityHour,
      sessionTrend,
    };
  } catch (error) {
    console.error('Failed to fetch User Activity:', error);
    throw new Error('User Activity data unavailable');
  }
}

/**
 * Check if Faro (Loki) is available
 */
export function isFaroAvailable(): boolean {
  const url = getLokiApiUrl();
  return url !== '';
}

/**
 * Get Dashboard Performance metrics
 *
 * Returns percentiles for dashboard loading and widget rendering:
 * - Initial load time (time to first data displayed)
 * - Full load time (time until all widgets loaded)
 * - Time to interactive
 * - Widget render time
 * - Widget errors count
 * - Data refresh duration
 */
export async function getDashboardPerformance(
  params: FaroQueryParams
): Promise<DashboardPerformanceData> {
  if (!isFaroAvailable()) {
    return Promise.reject(new Error('Dashboard Performance data unavailable'));
  }

  const timeRange = params.timeRange || '24h';
  const rangeMs = parseTimeRange(timeRange);
  const endMs = Date.now();
  const startMs = endMs - rangeMs;

  try {
    // Query Loki for dashboard and custom measurements in parallel
    const query = '{source="faro", type="rum"} |= "type=dashboard"';
    const customQuery = '{source="faro", type="rum"} |= "type=custom"';
    const [response, customResponse] = await Promise.all([
      executeLokiQuery(query, startMs, endMs),
      executeLokiQuery(customQuery, startMs, endMs),
    ]);
    const entries = extractLogEntries(response);
    const customEntries = extractLogEntries(customResponse);

    const allEntries = [...entries, ...customEntries];

    // Extract metric values
    const initialLoadValues = extractMetricValues(allEntries, 'initial_load')
      .concat(extractMetricValues(allEntries, 'initialLoad'))
      .concat(extractMetricValues(allEntries, 'dashboard_initial_load'));
    const fullLoadValues = extractMetricValues(allEntries, 'full_load')
      .concat(extractMetricValues(allEntries, 'fullLoad'))
      .concat(extractMetricValues(allEntries, 'dashboard_full_load'));
    const timeToInteractiveValues = extractMetricValues(allEntries, 'time_to_interactive')
      .concat(extractMetricValues(allEntries, 'timeToInteractive'))
      .concat(extractMetricValues(allEntries, 'tti'));
    const widgetRenderValues = extractMetricValues(allEntries, 'widget_render')
      .concat(extractMetricValues(allEntries, 'widgetRender'))
      .concat(extractMetricValues(allEntries, 'widget_render_time'));
    const dataRefreshValues = extractMetricValues(allEntries, 'data_refresh')
      .concat(extractMetricValues(allEntries, 'dataRefresh'))
      .concat(extractMetricValues(allEntries, 'refresh_duration'));

    // Count widget errors from exception logs
    const widgetErrorQuery = '{source="faro", type="rum"} |= "kind=exception" |= "widget"';
    let widgetErrors = 0;
    try {
      const errorResponse = await executeLokiQuery(widgetErrorQuery, startMs, endMs);
      widgetErrors = extractLogEntries(errorResponse).length;
    } catch {
      // Ignore error query failures
    }

    return {
      initialLoad: calculatePercentilesFromValues(initialLoadValues),
      fullLoad: calculatePercentilesFromValues(fullLoadValues),
      timeToInteractive: calculatePercentilesFromValues(timeToInteractiveValues),
      widgetRender: calculatePercentilesFromValues(widgetRenderValues),
      widgetErrors,
      dataRefresh: calculatePercentilesFromValues(dataRefreshValues),
    };
  } catch (error) {
    console.error('Failed to fetch Dashboard Performance:', error);
    throw new Error('Dashboard Performance data unavailable');
  }
}

/**
 * Get WebSocket Performance metrics
 *
 * LogQL Queries used:
 * - Latency: {source="faro", type="rum"} |= "type=websocket_latency" (round_trip_ms)
 * - Connect Time: {source="faro", type="rum"} |= "type=websocket" (connect_time_ms)
 * - Message Size: {source="faro", type="rum"} |= "type=websocket_message" (message_size_bytes)
 * - Errors: {source="faro", type="rum"} |= "kind=exception"
 *
 * Returns metrics for WebSocket connection health and message latency:
 * - Connection duration (connect_time_ms)
 * - Round-trip latency (round_trip_ms)
 * - Message size (message_size_bytes)
 * - Reconnect attempts count
 * - Connection failures count
 * - Error count (from exceptions)
 * - Messages received count
 */
export async function getWebSocketPerformance(
  params: FaroQueryParams
): Promise<WebSocketPerformanceData> {
  if (!isFaroAvailable()) {
    return Promise.reject(new Error('WebSocket Performance data unavailable'));
  }

  const timeRange = params.timeRange || '24h';
  const rangeMs = parseTimeRange(timeRange);
  const endMs = Date.now();
  const startMs = endMs - rangeMs;

  try {
    // Query all WebSocket data in parallel
    const latencyQuery = '{source="faro", type="rum"} |= "type=websocket_latency"';
    const connectQuery = '{source="faro", type="rum"} |= "type=websocket"';
    const messageQuery = '{source="faro", type="rum"} |= "type=websocket_message"';
    const wsErrorQuery = '{source="faro", type="rum"} |= "kind=exception" |= "websocket"';

    const [latencyResponse, connectResponse, messageResponse, wsErrorResult] = await Promise.all([
      executeLokiQuery(latencyQuery, startMs, endMs),
      executeLokiQuery(connectQuery, startMs, endMs),
      executeLokiQuery(messageQuery, startMs, endMs),
      executeLokiQuery(wsErrorQuery, startMs, endMs).catch(() => null),
    ]);

    const latencyEntries = extractLogEntries(latencyResponse);
    const connectEntries = extractLogEntries(connectResponse);
    const messageEntries = extractLogEntries(messageResponse);
    let errorCount = wsErrorResult ? extractLogEntries(wsErrorResult).length : 0;

    // Extract latency values (round_trip_ms)
    const messageLatencyValues = extractMetricValues(latencyEntries, 'round_trip_ms');

    // Extract connect time values (connect_time_ms)
    const connectionDurationValues = extractMetricValues(connectEntries, 'connect_time_ms');

    // Extract message size values (message_size_bytes)
    const messageSizeValues = extractMetricValues(messageEntries, 'message_size_bytes');

    // Extract processing time values
    const messageProcessingValues = extractMetricValues(messageEntries, 'processing_time_ms');

    // Count events from all entries
    let reconnectAttempts = 0;
    let connectionFailures = 0;
    const messagesReceived = messageEntries.length;

    const allEntries = [...connectEntries, ...latencyEntries, ...messageEntries];

    for (const entry of allEntries) {
      const parsed = getEntryData(entry);
      if (parsed.reconnect_attempt || parsed.reconnectAttempt || parsed.is_reconnect) {
        reconnectAttempts++;
      }
      if (parsed.connection_failure || parsed.connectionFailure || parsed.failed) {
        connectionFailures++;
      }
    }

    // Query for WebSocket events
    const eventQuery = '{source="faro", type="rum"} |= "kind=event" |= "websocket"';
    try {
      const eventResponse = await executeLokiQuery(eventQuery, startMs, endMs);
      const eventEntries = extractLogEntries(eventResponse);

      for (const entry of eventEntries) {
        const parsed = getEntryData(entry);
        const eventName = String(parsed.name || parsed.event || '');
        if (eventName.includes('reconnect')) {
          reconnectAttempts++;
        }
        if (eventName.includes('failure') || eventName.includes('error')) {
          connectionFailures++;
        }
      }
    } catch {
      // Ignore event query failures
    }

    return {
      connectionDuration: calculatePercentilesFromValues(connectionDurationValues),
      reconnectAttempts,
      connectionFailures,
      activeConnections: 0, // Would need real-time gauge data
      messageLatency: calculatePercentilesFromValues(messageLatencyValues),
      messageProcessing: calculatePercentilesFromValues(messageProcessingValues),
      messageSize: calculatePercentilesFromValues(messageSizeValues),
      messagesReceived,
      errorCount,
    };
  } catch (error) {
    console.error('Failed to fetch WebSocket Performance:', error);
    throw new Error('WebSocket Performance data unavailable');
  }
}

/**
 * Get API Performance metrics
 *
 * Tracks HTTP/Fetch API response times and success rates from the user's perspective.
 * Uses faro.tracing.fetch events which are automatically captured by FARO SDK.
 *
 * LogQL Query: {source="faro", type="rum"} |= "faro.tracing.fetch"
 *
 * Fields used:
 * - event_data_duration_ns: Response time in nanoseconds
 * - event_data_http.url: API endpoint URL
 * - event_data_http.method: HTTP method (GET, POST, etc.)
 * - event_data_http.status_code: HTTP status code
 */
// Cache for getApiPerformance — deduplicates concurrent calls with same timeRange
const apiPerformanceCache: Map<string, { promise: Promise<ApiPerformanceData>; timestamp: number }> = new Map();
const API_CACHE_TTL = 60_000; // 60 seconds

/** Clear the API performance cache (exposed for testing) */
export function clearApiPerformanceCache(): void {
  apiPerformanceCache.clear();
}

export function getApiPerformance(
  params: FaroQueryParams
): Promise<ApiPerformanceData> {
  if (!isFaroAvailable()) {
    return Promise.reject(new Error('API Performance data unavailable'));
  }

  const timeRange = params.timeRange || '24h';

  // Return cached promise if still fresh
  const cached = apiPerformanceCache.get(timeRange);
  if (cached && Date.now() - cached.timestamp < API_CACHE_TTL) {
    return cached.promise;
  }

  const promise = _fetchApiPerformance(timeRange);
  apiPerformanceCache.set(timeRange, { promise, timestamp: Date.now() });

  // Clean cache entry on failure so next call retries
  promise.catch(() => {
    apiPerformanceCache.delete(timeRange);
  });

  return promise;
}

async function _fetchApiPerformance(
  timeRange: string
): Promise<ApiPerformanceData> {
  const rangeMs = parseTimeRange(timeRange);
  const endMs = Date.now();
  const startMs = endMs - rangeMs;

  try {
    // Query Loki for fetch and XHR timing events in parallel
    const query = '{source="faro", type="rum"} |= "faro.tracing.fetch"';
    const xhrQuery = '{source="faro", type="rum"} |= "faro.tracing.xml-http-request"';
    const [response, xhrResponse] = await Promise.all([
      executeLokiQuery(query, startMs, endMs),
      executeLokiQuery(xhrQuery, startMs, endMs),
    ]);
    const entries = extractLogEntries(response);
    const xhrEntries = extractLogEntries(xhrResponse);

    const allEntries = [...entries, ...xhrEntries];

    // Extract response times (convert nanoseconds to milliseconds)
    const responseTimes: number[] = [];
    const endpointData: Map<string, { times: number[]; statuses: number[] }> = new Map();
    let successCount = 0;
    let errorCount = 0;

    for (const entry of allEntries) {
      const parsed = getEntryData(entry);

      // Extract duration (in nanoseconds, convert to ms)
      const durationNs = parseFloat(
        String(parsed['event_data_duration_ns'] || parsed['duration_ns'] || '0')
      );
      const durationMs = durationNs / 1_000_000;

      if (durationMs > 0) {
        responseTimes.push(durationMs);
      }

      // Extract URL and method
      const url = String(
        parsed['event_data_http.url'] || parsed['http.url'] || parsed['url'] || ''
      );
      const method = String(
        parsed['event_data_http.method'] || parsed['http.method'] || parsed['method'] || 'GET'
      );
      const statusCode = parseInt(
        String(parsed['event_data_http.status_code'] || parsed['http.status_code'] || parsed['status_code'] || '0'),
        10
      );

      // Track success/error
      if (statusCode >= 200 && statusCode < 400) {
        successCount++;
      } else if (statusCode >= 400) {
        errorCount++;
      }

      // Group by endpoint for slowest endpoints
      if (url && durationMs > 0) {
        // Extract path from URL for grouping
        let endpoint = url;
        try {
          const urlObj = new URL(url);
          endpoint = urlObj.pathname;
        } catch {
          // Keep full URL if parsing fails
        }

        const key = `${method}:${endpoint}`;
        if (!endpointData.has(key)) {
          endpointData.set(key, { times: [], statuses: [] });
        }
        const data = endpointData.get(key)!;
        data.times.push(durationMs);
        data.statuses.push(statusCode);
      }
    }

    // Calculate percentiles for response time
    const responseTime = calculatePercentilesFromValues(responseTimes);

    // Calculate success/error rates
    const totalRequests = successCount + errorCount;
    const successRate = totalRequests > 0 ? (successCount / totalRequests) * 100 : 100;
    const errorRate = totalRequests > 0 ? (errorCount / totalRequests) * 100 : 0;

    // Build slowest endpoints list (top 5 by P95)
    const slowestEndpoints: ApiEndpointSummary[] = [];
    for (const [key, data] of endpointData.entries()) {
      const [method, endpoint] = key.split(':');
      const p95 = calculatePercentile(data.times, 95);
      const endpointSuccessCount = data.statuses.filter(s => s >= 200 && s < 400).length;
      const endpointSuccessRate = data.statuses.length > 0
        ? (endpointSuccessCount / data.statuses.length) * 100
        : 100;

      slowestEndpoints.push({
        endpoint,
        method,
        p95,
        count: data.times.length,
        successRate: Math.round(endpointSuccessRate * 10) / 10,
      });
    }

    // Sort by P95 descending (consumer controls limit via slice)
    slowestEndpoints.sort((a, b) => b.p95 - a.p95);

    // Build trend data (hourly breakdown)
    const trendData: ApiTrendPoint[] = buildApiTrendData(allEntries, startMs, endMs);

    return {
      responseTime,
      requestCount: allEntries.length,
      successRate: Math.round(successRate * 10) / 10,
      errorRate: Math.round(errorRate * 10) / 10,
      slowestEndpoints,
      trendData,
    };
  } catch (error) {
    console.error('Failed to fetch API Performance:', error);
    throw new Error('API Performance data unavailable');
  }
}

/**
 * Helper function to calculate a specific percentile from values
 */
function calculatePercentile(values: number[], percentile: number): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const index = Math.ceil((percentile / 100) * sorted.length) - 1;
  return Math.round(sorted[Math.max(0, index)] * 100) / 100;
}

/**
 * Build hourly trend data for API performance
 */
function buildApiTrendData(
  entries: FaroLogEntry[],
  startMs: number,
  endMs: number
): ApiTrendPoint[] {
  const hourlyData: Map<string, number[]> = new Map();

  for (const entry of entries) {
    const parsed = getEntryData(entry);
    // Use Loki timestamp (added during extraction) or fallback to entry timestamp
    // Cast through unknown to access dynamically added _lokiTimestamp property
    const entryWithTimestamp = entry as unknown as {
      _lokiTimestamp?: string;
    };
    const timestamp = String(
      entryWithTimestamp._lokiTimestamp || parsed['timestamp'] || ''
    );

    if (!timestamp) {
      continue;
    }

    // Parse timestamp to get hour bucket
    let hourKey: string;
    try {
      const date = new Date(timestamp);
      if (isNaN(date.getTime())) {
        continue;
      }
      date.setMinutes(0, 0, 0);
      hourKey = date.toISOString();
    } catch {
      continue;
    }

    const durationNs = parseFloat(
      String(parsed['event_data_duration_ns'] || parsed['duration_ns'] || '0')
    );
    const durationMs = durationNs / 1_000_000;

    if (durationMs > 0) {
      if (!hourlyData.has(hourKey)) {
        hourlyData.set(hourKey, []);
      }
      hourlyData.get(hourKey)!.push(durationMs);
    }
  }

  // Convert to trend points
  const trendData: ApiTrendPoint[] = [];
  for (const [timestamp, times] of hourlyData.entries()) {
    trendData.push({
      timestamp,
      p50: calculatePercentile(times, 50),
      p95: calculatePercentile(times, 95),
      count: times.length,
    });
  }

  // Sort by timestamp
  trendData.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

  return trendData;
}

/**
 * Get Browser & Device Analytics
 *
 * Tracks browser distribution, device types, and OS usage.
 * Uses browser metadata captured in every FARO event.
 *
 * Fields used:
 * - browser_name: Browser name (Chrome, Firefox, Safari, etc.)
 * - browser_version: Browser version
 * - browser_mobile: true/false for device type
 * - browser_os: Operating system
 */
export async function getBrowserAnalytics(
  params: FaroQueryParams
): Promise<BrowserAnalyticsData> {
  if (!isFaroAvailable()) {
    return Promise.reject(new Error('Browser Analytics data unavailable'));
  }

  const timeRange = params.timeRange || '24h';
  const rangeMs = parseTimeRange(timeRange);
  const endMs = Date.now();
  const startMs = endMs - rangeMs;

  try {
    // Query Loki for events with browser metadata
    // Use measurement events as they have browser info
    const query = '{source="faro", type="rum"} |= "browser_name"';
    const response = await executeLokiQuery(query, startMs, endMs);
    const entries = extractLogEntries(response);

    // Track unique sessions per browser/device
    const sessionBrowserMap: Map<string, string> = new Map(); // session_id -> browser_name
    const sessionMobileMap: Map<string, boolean> = new Map(); // session_id -> is_mobile
    const sessionOSMap: Map<string, string> = new Map(); // session_id -> os_name
    const browserVersionCount: Map<string, Map<string, number>> = new Map(); // browser -> version -> count

    // Track hourly browser data
    const hourlyBrowserData: Map<string, Map<string, Set<string>>> = new Map(); // hour -> browser -> sessions

    for (const entry of entries) {
      const parsed = getEntryData(entry);

      const sessionId = String(parsed['session_id'] || parsed['sessionId'] || '');
      const browserName = String(parsed['browser_name'] || parsed['browserName'] || 'Unknown');
      const browserVersion = String(parsed['browser_version'] || parsed['browserVersion'] || '');
      const isMobile = String(parsed['browser_mobile'] || parsed['browserMobile'] || 'false') === 'true';
      const osName = String(parsed['browser_os'] || parsed['browserOs'] || parsed['os_name'] || 'Unknown');
      const timestamp = String(parsed['timestamp'] || '');

      if (sessionId) {
        // Map session to browser/device/os
        if (!sessionBrowserMap.has(sessionId)) {
          sessionBrowserMap.set(sessionId, browserName);
          sessionMobileMap.set(sessionId, isMobile);
          sessionOSMap.set(sessionId, osName);

          // Track version
          if (!browserVersionCount.has(browserName)) {
            browserVersionCount.set(browserName, new Map());
          }
          const versionMap = browserVersionCount.get(browserName)!;
          versionMap.set(browserVersion, (versionMap.get(browserVersion) || 0) + 1);
        }

        // Track hourly trend
        if (timestamp) {
          try {
            const date = new Date(timestamp);
            date.setMinutes(0, 0, 0);
            const hourKey = date.toISOString();

            if (!hourlyBrowserData.has(hourKey)) {
              hourlyBrowserData.set(hourKey, new Map());
            }
            const hourMap = hourlyBrowserData.get(hourKey)!;
            if (!hourMap.has(browserName)) {
              hourMap.set(browserName, new Set());
            }
            hourMap.get(browserName)!.add(sessionId);
          } catch {
            // Ignore invalid timestamps
          }
        }
      }
    }

    // Calculate browser distribution
    const browserCounts: Map<string, number> = new Map();
    for (const browser of sessionBrowserMap.values()) {
      browserCounts.set(browser, (browserCounts.get(browser) || 0) + 1);
    }

    const totalSessions = sessionBrowserMap.size;
    const browsers: BrowserSummary[] = [];

    for (const [name, count] of browserCounts.entries()) {
      // Find most common version
      let topVersion: string | undefined;
      const versionMap = browserVersionCount.get(name);
      if (versionMap && versionMap.size > 0) {
        let maxCount = 0;
        for (const [version, vCount] of versionMap.entries()) {
          if (vCount > maxCount) {
            maxCount = vCount;
            topVersion = version;
          }
        }
      }

      browsers.push({
        name,
        sessions: count,
        percentage: totalSessions > 0 ? Math.round((count / totalSessions) * 1000) / 10 : 0,
        topVersion,
      });
    }

    // Sort by session count descending
    browsers.sort((a, b) => b.sessions - a.sessions);

    // Calculate device type distribution
    let desktopCount = 0;
    let mobileCount = 0;
    for (const isMobile of sessionMobileMap.values()) {
      if (isMobile) {
        mobileCount++;
      } else {
        desktopCount++;
      }
    }

    const deviceTypes = {
      desktop: desktopCount,
      mobile: mobileCount,
      desktopPercentage: totalSessions > 0 ? Math.round((desktopCount / totalSessions) * 1000) / 10 : 0,
      mobilePercentage: totalSessions > 0 ? Math.round((mobileCount / totalSessions) * 1000) / 10 : 0,
    };

    // Calculate OS distribution
    const osCounts: Map<string, number> = new Map();
    for (const os of sessionOSMap.values()) {
      // Normalize OS names
      let normalizedOS = os;
      if (os.toLowerCase().includes('mac')) {
        normalizedOS = 'macOS';
      } else if (os.toLowerCase().includes('windows')) {
        normalizedOS = 'Windows';
      } else if (os.toLowerCase().includes('linux')) {
        normalizedOS = 'Linux';
      } else if (os.toLowerCase().includes('ios')) {
        normalizedOS = 'iOS';
      } else if (os.toLowerCase().includes('android')) {
        normalizedOS = 'Android';
      }
      osCounts.set(normalizedOS, (osCounts.get(normalizedOS) || 0) + 1);
    }

    const operatingSystems: OSSummary[] = [];
    for (const [name, count] of osCounts.entries()) {
      operatingSystems.push({
        name,
        sessions: count,
        percentage: totalSessions > 0 ? Math.round((count / totalSessions) * 1000) / 10 : 0,
      });
    }
    operatingSystems.sort((a, b) => b.sessions - a.sessions);

    // Build browser trend data
    const browserTrend: BrowserTrendPoint[] = [];
    for (const [timestamp, browserMap] of hourlyBrowserData.entries()) {
      for (const [browser, sessions] of browserMap.entries()) {
        browserTrend.push({
          timestamp,
          browser,
          sessions: sessions.size,
        });
      }
    }
    browserTrend.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

    return {
      browsers,
      deviceTypes,
      operatingSystems,
      totalSessions,
      browserTrend,
    };
  } catch (error) {
    console.error('Failed to fetch Browser Analytics:', error);
    throw new Error('Browser Analytics data unavailable');
  }
}

