/**
 * Auth Analytics Service
 *
 * Service to query Auth Service backend for authentication security metrics
 * to display in the Analytics tab.
 *
 * Features:
 * - Login tracking (successful/failed logins, success rate)
 * - Failed login analysis (by reason)
 * - Brute force detection (suspicious IPs)
 * - Credential stuffing detection
 * - Account lockouts
 * - Real-time threat monitoring (active IP attacks)
 * - Password spray detection
 *
 * API: https://{env}.auth.docbits.com/v2/analytics
 */

import AbstractApiService from 'src/services/abstractApiService';
import { AUTH_URL } from 'src/pages/APIs';

/**
 * Query parameters for auth analytics endpoints
 */
export interface AuthMetricsParams {
  time_period?: 'today' | 'week' | '30days';
}

/**
 * Login tracking metrics
 */
export interface LoginTrackingMetrics {
  total: number;
  successful: number;
  failed: number;
  success_rate: number; // Percentage
}

/**
 * Failed login breakdown by reason
 */
export interface FailedLoginsMetrics {
  total: number;
  by_reason: {
    invalid_credentials: number;
    user_not_found: number;
    account_locked: number;
  };
}

/**
 * Suspicious IP information
 */
export interface SuspiciousIp {
  ip: string;
  attempts: number;
  first_seen: string; // ISO 8601
  last_seen: string; // ISO 8601
}

/**
 * Brute force detection metrics
 */
export interface BruteForceDetectionMetrics {
  total_suspicious_ips: number;
  suspicious_ips: SuspiciousIp[];
}

/**
 * Credential stuffing metrics
 */
export interface CredentialStuffingMetrics {
  total: number;
}

/**
 * Account lockout metrics
 */
export interface AccountLockoutsMetrics {
  total: number;
}

/**
 * Real-time threat detail
 */
export interface RealTimeThreatDetail {
  ip_address: string;
  failed_attempts: number;
  first_attempt: string; // ISO 8601
  last_attempt: string; // ISO 8601
  is_active: boolean;
}

/**
 * Real-time threat metrics
 */
export interface RealTimeThreatsMetrics {
  active_ip_attacks: number;
  details: RealTimeThreatDetail[];
}

/**
 * Password spray metrics
 */
export interface PasswordSprayMetrics {
  total_patterns: number;
}

/**
 * Comprehensive auth security metrics
 */
export interface AuthMetrics {
  login_tracking: LoginTrackingMetrics;
  failed_logins: FailedLoginsMetrics;
  brute_force_detection: BruteForceDetectionMetrics;
  credential_stuffing: CredentialStuffingMetrics;
  account_lockouts: AccountLockoutsMetrics;
  real_time_threats: RealTimeThreatsMetrics;
  password_spray: PasswordSprayMetrics;
}

/**
 * GET /v2/analytics/auth/metrics response
 */
export interface AuthMetricsResponse {
  org_id: string;
  time_period: 'today' | 'week' | '30days';
  start_time: string; // ISO 8601
  end_time: string; // ISO 8601
  metrics: AuthMetrics;
}

/**
 * IP attack detail
 */
export interface IpAttackDetail {
  ip_address: string;
  failed_attempts: number;
  first_attempt: string; // ISO 8601
  last_attempt: string; // ISO 8601
  is_active: boolean;
}

/**
 * GET /v2/analytics/auth/ip-attacks response
 */
export interface AuthIpAttacksResponse {
  org_id: string;
  time_period: 'today' | 'week' | '30days';
  ip_attacks: IpAttackDetail[];
  total: number;
}

/**
 * Auth Analytics Service
 *
 * Provides methods to query auth security metrics from the Auth Service.
 * Extends AbstractApiService for automatic Bearer token handling.
 *
 * Uses getWithoutOrgId() since auth endpoints extract org_id from JWT token.
 */
export default class AuthAnalyticsService extends AbstractApiService {
  public constructor() {
    super({});
  }

  /**
   * Get comprehensive auth security metrics
   *
   * @param params - Query parameters
   * @param params.time_period - Time range: today, week, or 30days (default: today)
   * @returns Promise resolving to auth metrics data
   *
   * @example
   * const service = new AuthAnalyticsService();
   * const metrics = await service.getAuthMetrics({ time_period: 'week' });
   * console.log(metrics.metrics.login_tracking.success_rate);
   */
  public async getAuthMetrics(
    params: AuthMetricsParams = {}
  ): Promise<AuthMetricsResponse> {
    const queryParams = new URLSearchParams();

    if (params.time_period) {
      queryParams.append('time_period', params.time_period);
    }

    const queryString = queryParams.toString();
    const endpoint = `${AUTH_URL}/v2/analytics/auth/metrics${
      queryString ? '?' + queryString : ''
    }`;

    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get suspicious IP address details
   *
   * @param params - Query parameters
   * @param params.time_period - Time range: today, week, or 30days (default: today)
   * @returns Promise resolving to IP attacks data
   *
   * @example
   * const service = new AuthAnalyticsService();
   * const attacks = await service.getIpAttacks({ time_period: 'today' });
   * const activeAttacks = attacks.ip_attacks.filter(ip => ip.is_active);
   */
  public async getIpAttacks(
    params: AuthMetricsParams = {}
  ): Promise<AuthIpAttacksResponse> {
    const queryParams = new URLSearchParams();

    if (params.time_period) {
      queryParams.append('time_period', params.time_period);
    }

    const queryString = queryParams.toString();
    const endpoint = `${AUTH_URL}/v2/analytics/auth/ip-attacks${
      queryString ? '?' + queryString : ''
    }`;

    return await this.getWithoutOrgId(endpoint);
  }
}
