/**
 * API Metrics Service
 *
 * Aggregated service for API performance metrics displayed in the Analytics API tab.
 * Combines data from:
 * - FaroMetricsService: Client-side API performance (response times from user perspective)
 * - AnalyticsService: Backend document processing metrics
 * - Prometheus: Infrastructure health (Redis, DB, Celery)
 *
 * @see /settings/analytics?tab=api
 */

import { getApiPerformance, isFaroAvailable } from '../faro/FaroMetricsService';
import type {
  ApiPerformanceData,
  ApiEndpointSummary,
  ApiTrendPoint,
} from '../faro/types';
import AnalyticsService from './AnalyticsService';
import type {
  ModulePerformanceResponse,
  ExecutiveSummaryResponse,
  ValidationErrorsResponse,
} from './AnalyticsService';
import { DOC2API_URL } from 'src/pages/APIs';
import axios from 'axios';

// ============================================================================
// TypeScript Response Interfaces
// ============================================================================

/**
 * API Health Overview - Aggregated KPIs for the top stat cards
 */
export interface ApiHealthOverview {
  /** Health score (0-100) calculated from error rate, latency, and throughput */
  healthScore: number;
  /** Health category based on score */
  healthCategory: 'excellent' | 'good' | 'fair' | 'poor';
  /** Total API requests in the time period */
  totalRequests: number;
  /** Request trend compared to previous period (-100 to +100 percent) */
  requestTrend: number;
  /** Error rate percentage (0-100) */
  errorRate: number;
  /** Error rate trend compared to previous period */
  errorTrend: number;
  /** Average response time in milliseconds */
  avgResponseTime: number;
  /** P95 response time in milliseconds */
  p95ResponseTime: number;
}

/**
 * Request volume time series data point
 */
export interface RequestVolumePoint {
  /** Timestamp (ISO string) */
  timestamp: string;
  /** Requests per minute at this timestamp */
  requestsPerMinute: number;
}

/**
 * Response time percentiles over time
 */
export interface ResponseTimePercentiles {
  /** Timestamps for the time series */
  timestamps: string[];
  /** P50 (median) values */
  p50: number[];
  /** P75 values */
  p75: number[];
  /** P95 values */
  p95: number[];
  /** P99 values */
  p99: number[];
}

/**
 * HTTP method distribution
 */
export interface MethodDistribution {
  /** HTTP method name */
  method: string;
  /** Request count for this method */
  count: number;
  /** Percentage of total requests */
  percentage: number;
}

/**
 * Infrastructure health status
 */
export interface InfrastructureHealth {
  redis: {
    status: 'healthy' | 'warning' | 'critical' | 'unknown';
    poolUsed: number;
    poolTotal: number;
    avgLatencyMs: number;
  };
  database: {
    status: 'healthy' | 'warning' | 'critical' | 'unknown';
    connectionsActive: number;
    connectionsMax: number;
    avgQueryTimeMs: number;
  };
  celery: {
    status: 'healthy' | 'warning' | 'critical' | 'unknown';
    workersOnline: number;
    workersTotal: number;
    tasksPending: number;
  };
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Convert hours to time range string format (e.g., '24h', '7d')
 */
function hoursToTimeRange(hours: number): string {
  if (hours <= 24) {
    return `${hours}h`;
  }
  const days = Math.floor(hours / 24);
  return `${days}d`;
}

/**
 * Calculate health score based on error rate, latency, and availability
 */
function calculateHealthScore(
  errorRate: number,
  p95LatencyMs: number,
  successRate: number
): { score: number; category: 'excellent' | 'good' | 'fair' | 'poor' } {
  // Weight factors
  const errorWeight = 0.4; // 40% weight on error rate
  const latencyWeight = 0.3; // 30% weight on latency
  const availabilityWeight = 0.3; // 30% weight on success rate

  // Error rate score (0% error = 100, 5%+ error = 0)
  const errorScore = Math.max(0, 100 - errorRate * 20);

  // Latency score (P95 < 200ms = 100, P95 > 2000ms = 0)
  const latencyScore = Math.max(
    0,
    Math.min(100, 100 - (p95LatencyMs - 200) / 18)
  );

  // Success rate is already 0-100
  const availabilityScore = successRate;

  // Calculate weighted score
  const score = Math.round(
    errorScore * errorWeight +
      latencyScore * latencyWeight +
      availabilityScore * availabilityWeight
  );

  // Determine category
  let category: 'excellent' | 'good' | 'fair' | 'poor';
  if (score >= 90) {
    category = 'excellent';
  } else if (score >= 70) {
    category = 'good';
  } else if (score >= 50) {
    category = 'fair';
  } else {
    category = 'poor';
  }

  return { score, category };
}

// ============================================================================
// API Metrics Service Class
// ============================================================================

export default class ApiMetricsService {
  private analyticsService: AnalyticsService;

  constructor() {
    this.analyticsService = new AnalyticsService();
  }

  /**
   * Check if API metrics are available (Faro is configured)
   */
  public isAvailable(): boolean {
    return isFaroAvailable();
  }

  /**
   * Get API health overview with aggregated KPIs
   *
   * @param hours - Time range in hours (default: 1)
   */
  public async getApiHealthOverview(hours: number = 1): Promise<ApiHealthOverview> {
    const timeRange = hoursToTimeRange(hours);

    try {
      // Get API performance from Faro
      const apiPerformance = await getApiPerformance({ timeRange });

      // Calculate health score
      const { score, category } = calculateHealthScore(
        apiPerformance.errorRate,
        apiPerformance.responseTime.p95,
        apiPerformance.successRate
      );

      // TODO: Calculate trend by comparing with previous period
      // For now, use placeholder values
      const requestTrend = 0;
      const errorTrend = 0;

      return {
        healthScore: score,
        healthCategory: category,
        totalRequests: apiPerformance.requestCount,
        requestTrend,
        errorRate: apiPerformance.errorRate,
        errorTrend,
        avgResponseTime: apiPerformance.responseTime.p50,
        p95ResponseTime: apiPerformance.responseTime.p95,
      };
    } catch (error) {
      console.error('[ApiMetricsService] Failed to get health overview:', error);
      // Return default values when data is unavailable
      return {
        healthScore: 0,
        healthCategory: 'poor',
        totalRequests: 0,
        requestTrend: 0,
        errorRate: 0,
        errorTrend: 0,
        avgResponseTime: 0,
        p95ResponseTime: 0,
      };
    }
  }

  /**
   * Get request volume time series data
   *
   * @param hours - Time range in hours (default: 24)
   */
  public async getRequestVolume(
    hours: number = 24
  ): Promise<RequestVolumePoint[]> {
    const timeRange = hoursToTimeRange(hours);

    try {
      const apiPerformance = await getApiPerformance({ timeRange });

      // Convert trend data to request volume points
      const volumeData: RequestVolumePoint[] = apiPerformance.trendData.map(
        (point: ApiTrendPoint) => ({
          timestamp: point.timestamp,
          // Estimate requests per minute from hourly count
          requestsPerMinute: Math.round(point.count / 60),
        })
      );

      return volumeData;
    } catch (error) {
      console.error('[ApiMetricsService] Failed to get request volume:', error);
      return [];
    }
  }

  /**
   * Get response time percentiles over time
   *
   * @param hours - Time range in hours (default: 24)
   */
  public async getResponseTimePercentiles(
    hours: number = 24
  ): Promise<ResponseTimePercentiles> {
    const timeRange = hoursToTimeRange(hours);

    try {
      const apiPerformance = await getApiPerformance({ timeRange });

      // Extract timestamps and percentile values from trend data
      const timestamps: string[] = [];
      const p50: number[] = [];
      const p75: number[] = [];
      const p95: number[] = [];
      const p99: number[] = [];

      for (const point of apiPerformance.trendData) {
        timestamps.push(point.timestamp);
        p50.push(point.p50);
        // Estimate p75 and p99 from available data
        p75.push(Math.round(point.p50 + (point.p95 - point.p50) * 0.4));
        p95.push(point.p95);
        p99.push(Math.round(point.p95 * 1.3)); // Estimate p99 as 130% of p95
      }

      return { timestamps, p50, p75, p95, p99 };
    } catch (error) {
      console.error(
        '[ApiMetricsService] Failed to get response time percentiles:',
        error
      );
      return { timestamps: [], p50: [], p75: [], p95: [], p99: [] };
    }
  }

  /**
   * Get top slowest endpoints
   *
   * @param hours - Time range in hours (default: 1)
   * @param limit - Maximum number of endpoints to return (default: 10)
   */
  public async getTopSlowEndpoints(
    hours: number = 1,
    limit: number = 10
  ): Promise<ApiEndpointSummary[]> {
    const timeRange = hoursToTimeRange(hours);

    try {
      const apiPerformance = await getApiPerformance({ timeRange });

      // Sort by P95 descending and return top N
      const sorted = [...apiPerformance.slowestEndpoints].sort(
        (a, b) => b.p95 - a.p95
      );

      return sorted.slice(0, limit);
    } catch (error) {
      console.error(
        '[ApiMetricsService] Failed to get slow endpoints:',
        error
      );
      return [];
    }
  }

  /**
   * Get HTTP method distribution
   *
   * @param hours - Time range in hours (default: 1)
   */
  public async getMethodDistribution(
    hours: number = 1
  ): Promise<MethodDistribution[]> {
    // Note: FaroMetricsService doesn't directly provide method distribution
    // We'll estimate from the slowest endpoints data or use backend analytics

    try {
      // Try to get module performance from analytics service
      const modulePerformance = await this.analyticsService.getModulePerformance(
        hours
      );

      // Default distribution based on typical API patterns
      // This should be replaced with actual data when available
      const methods: MethodDistribution[] = [
        { method: 'GET', count: 0, percentage: 65 },
        { method: 'POST', count: 0, percentage: 25 },
        { method: 'PUT', count: 0, percentage: 5 },
        { method: 'DELETE', count: 0, percentage: 3 },
        { method: 'PATCH', count: 0, percentage: 2 },
      ];

      // Calculate actual counts from total request estimate
      const totalRequests =
        modulePerformance.module_performance?.reduce(
          (sum, m) => sum + m.execution_count,
          0
        ) || 1000;

      for (const method of methods) {
        method.count = Math.round((totalRequests * method.percentage) / 100);
      }

      return methods;
    } catch (error) {
      console.error(
        '[ApiMetricsService] Failed to get method distribution:',
        error
      );
      // Return default distribution
      return [
        { method: 'GET', count: 650, percentage: 65 },
        { method: 'POST', count: 250, percentage: 25 },
        { method: 'PUT', count: 50, percentage: 5 },
        { method: 'DELETE', count: 30, percentage: 3 },
        { method: 'PATCH', count: 20, percentage: 2 },
      ];
    }
  }

  /**
   * Get infrastructure health status (Redis, DB, Celery)
   *
   * Note: This requires backend Prometheus metrics endpoints.
   * Returns mock data if endpoints are unavailable.
   */
  public async getInfrastructureHealth(): Promise<InfrastructureHealth> {
    // Default health status
    const health: InfrastructureHealth = {
      redis: {
        status: 'unknown',
        poolUsed: 0,
        poolTotal: 10,
        avgLatencyMs: 0,
      },
      database: {
        status: 'unknown',
        connectionsActive: 0,
        connectionsMax: 20,
        avgQueryTimeMs: 0,
      },
      celery: {
        status: 'unknown',
        workersOnline: 0,
        workersTotal: 3,
        tasksPending: 0,
      },
    };

    try {
      // Try to fetch health endpoint from backend
      const response = await axios.get(`${DOC2API_URL}/api/health`, {
        timeout: 5000,
      });

      if (response.data) {
        // Redis health
        if (response.data.redis !== undefined) {
          health.redis.status = response.data.redis ? 'healthy' : 'critical';
          health.redis.poolUsed = response.data.redis_pool_used || 5;
          health.redis.poolTotal = response.data.redis_pool_total || 10;
        }

        // Database health
        if (response.data.database !== undefined) {
          health.database.status = response.data.database
            ? 'healthy'
            : 'critical';
          health.database.connectionsActive =
            response.data.db_connections_active || 5;
          health.database.connectionsMax =
            response.data.db_connections_max || 20;
        }

        // Celery health (from flower or backend)
        if (response.data.celery !== undefined) {
          health.celery.status = response.data.celery ? 'healthy' : 'critical';
          health.celery.workersOnline = response.data.celery_workers || 3;
          health.celery.tasksPending = response.data.celery_pending || 0;
        }
      }

      // Determine status based on utilization
      if (health.redis.poolTotal > 0) {
        const redisUsage = health.redis.poolUsed / health.redis.poolTotal;
        if (redisUsage > 0.8) {
          health.redis.status = 'warning';
        } else if (redisUsage > 0.95) {
          health.redis.status = 'critical';
        }
      }

      if (health.database.connectionsMax > 0) {
        const dbUsage =
          health.database.connectionsActive / health.database.connectionsMax;
        if (dbUsage > 0.8) {
          health.database.status = 'warning';
        } else if (dbUsage > 0.95) {
          health.database.status = 'critical';
        }
      }
    } catch {
      console.warn(
        '[ApiMetricsService] Health endpoint unavailable, using defaults'
      );
      // Keep default unknown status
    }

    return health;
  }

  /**
   * Get raw API performance data from Faro
   * Useful for accessing all available metrics directly
   */
  public async getRawApiPerformance(
    hours: number = 1
  ): Promise<ApiPerformanceData | null> {
    const timeRange = hoursToTimeRange(hours);

    try {
      return await getApiPerformance({ timeRange });
    } catch (error) {
      console.error(
        '[ApiMetricsService] Failed to get raw API performance:',
        error
      );
      return null;
    }
  }

  /**
   * Get module performance from backend analytics
   * Provides processing module metrics (OCR, extraction, etc.)
   */
  public async getModulePerformance(
    hours: number = 168
  ): Promise<ModulePerformanceResponse | null> {
    try {
      return await this.analyticsService.getModulePerformance(hours);
    } catch (error) {
      console.error(
        '[ApiMetricsService] Failed to get module performance:',
        error
      );
      return null;
    }
  }

  /**
   * Get executive summary from backend analytics
   * Provides high-level KPIs for document processing
   */
  public async getExecutiveSummary(
    period: string = '24h'
  ): Promise<ExecutiveSummaryResponse | null> {
    try {
      return await this.analyticsService.getExecutiveSummary(period);
    } catch (error) {
      console.error(
        '[ApiMetricsService] Failed to get executive summary:',
        error
      );
      return null;
    }
  }

  /**
   * Get validation errors for error analysis
   */
  public async getValidationErrors(
    hours: number = 24
  ): Promise<ValidationErrorsResponse | null> {
    try {
      return await this.analyticsService.getValidationErrors(hours);
    } catch (error) {
      console.error(
        '[ApiMetricsService] Failed to get validation errors:',
        error
      );
      return null;
    }
  }
}

// Export singleton instance for convenience
export const apiMetricsService = new ApiMetricsService();
